class Solution
{
public:
    int minCostII(vector< vector< int >>& costs)
    {
        if (costs.empty())
        {
            return 0;
        }
        int k = costs[0].size();
        vector< int>dp(k);
        for (auto&row : costs)
        {
            int first = INT_MAX, second = INT_MAX, idx = - 1;
            for (int j = 0; j < k;++j)
            {
                if (dp[j] < first)
                {
                    second = first;
                    first = dp[j];
                    idx = j;
                }
                else second = min(second, dp[j]);
            }
            vector< int>next(k);
            for (int j = 0; j < k;++j)
            {
                next[j] = row[j] + (j == idx ? second : first);
            }
            dp.swap(next);
        }
        return*min_element(dp.begin(), dp.end());
    }
};
